// Tutorial content: one slide per screen. `caption` is what staff read on screen (Taglish);
// `say` is the English voice-over (public/tutorial/audio/<id>.m4a, generated by scripts/tutorial-audio.mjs).
// Safe to import on the client — plain data only.

export type Slide = { id: string; chapter: string; title: string; image: string; caption: string; say: string };
export type Chapter = { key: string; label: string; who: string };

